// How many open tasks are overdue, due today, or due in the next 7 days. It is computed during
// render from the tasks it is given, never copied into state by an effect, so it can't be one
// render behind. "Today" comes from the app's clock, so tests and checks control it.
import { daysUntil } from "@/lib/format";
import { todayISO } from "@/lib/clock";
import type { Task } from "../types";

export interface DueSummary {
  overdue: number;
  today: number;
  upcoming: number;
}

export function useDueSummary(tasks: readonly Task[]): DueSummary {
  const today = todayISO();
  const summary: DueSummary = { overdue: 0, today: 0, upcoming: 0 };
  for (const task of tasks) {
    if (task.status === "done" || task.due_on === null) continue;
    const days = daysUntil(task.due_on, today);
    if (days < 0) summary.overdue += 1;
    else if (days === 0) summary.today += 1;
    else if (days <= 7) summary.upcoming += 1;
  }
  return summary;
}

// A copy of a value that changes only once the value has stopped changing for delayMs. Typing
// "grace" quickly then sends one search instead of five. Each change restarts the timer, and the
// effect's cleanup cancels the timer the next change replaces.
import { useEffect, useState } from "react";

export function useDebouncedValue<T>(value: T, delayMs: number): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(timer);
  }, [value, delayMs]);

  return debounced;
}

// A modal dialog on the native <dialog> element. showModal() gives focus trapping, Escape to
// close, an inert page behind, and focus returned to the opener, all from the browser. React
// controls it with the open prop: an effect calls showModal() or close() to match, and the
// dialog's close event (Escape, or close() itself) reports back through onClose.
// ...
export function Dialog({ open, onClose, title, className, children }: DialogProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    if (!open && dialog.open) dialog.close();
  }, [open]);

  return (
    <dialog ref={ref} data-ui="dialog" aria-labelledby={titleId} className={clsx(styles.dialog, className)} onClose={onClose}>
      {/* The content mounts only while open, so a form inside starts fresh every time. */}
      {open && (
        <>
          <h2 id={titleId} className={styles.title}>
            {title}
          </h2>
          {children}
        </>
      )}
    </dialog>
  );
}

// Whether a CSS media query matches, kept current as the window resizes or the system theme
// changes. useSyncExternalStore subscribes to the MediaQueryList's change event.
import { useSyncExternalStore } from "react";

export function useMediaQuery(query: string): boolean {
  return useSyncExternalStore(
    (onChange) => {
      const list = window.matchMedia(query);
      list.addEventListener("change", onChange);
      return () => list.removeEventListener("change", onChange);
    },
    () => window.matchMedia(query).matches,
    () => false,
  );
}
